    public function __construct(private $db,private string$p){}
    public function forIssuer($issuer,$actor):array{$issuer=\IssuerPolicy::id($issuer);$actor=\IssuerPolicy::id($actor);$source=new Api16ReviewedExternalReversal(1,[]);$source->assertSchema($this->db,$this->p);return \IssuerTransaction::run($this->db,$this->p,$source->tables(),function()use($issuer,$actor):array{Reconciliation::authorize($this->db,$this->p,$issuer,$actor,'reconcile');Reconciliation::authorize($this->db,$this->p,$issuer,$actor,'reconcile_api_components');$balance=new \CompanyInvoiceBalance($this->db,$this->p);$out=[];$positions=[];foreach(\IssuerStorage::query($this->db,"SELECT r.origin_id,r.payment_id,r.operation_id,n.invoiceid,n.date FROM {$this->p}bb_api_receipts r JOIN {$this->p}invoicepaymentrecords n ON n.id=r.payment_id JOIN {$this->p}invoices i ON i.id=n.invoiceid AND i.issuer_id=r.issuer_id WHERE r.issuer_id=? ORDER BY r.payment_id DESC LIMIT 50",[$issuer])->result_array()as$row){$invoice=(int)$row['invoiceid'];$payment=(int)$row['payment_id'];$position=$positions[$invoice]??=$balance->inOwned($issuer,$actor,$invoice);$component=$position['components'][$payment]??null;if(!$component||$component['basis']!==\CompanyBankComponentsData::API16_BASIS)continue;[$origin]=(new ApiService($this->db,$this->p))->receiptOriginInOwnedTransaction($issuer,$actor,(int)$row['origin_id']);$reverse=$position['reversals'][$payment]??null;$out[$payment]=['payment_id'=>$payment,'invoice_id'=>$invoice,'origin_id'=>(int)$origin['id'],'operation_id'=>(int)$row['operation_id'],'number20'=>$origin['remote_id'],'account_id'=>$origin['account_id'],'environment'=>$origin['environment'],'agreement'=>$origin['agreement_number'],'original_date'=>$row['date'],'original_fingerprint'=>\CompanyBankComponentsData::fromCaptured($component)->fingerprint(),'cash_principal'=>$component['cash_principal'],'paid'=>$component['paid'],'principal_extinguished'=>$component['principal_extinguished'],'discount'=>$component['discount'],'abatement'=>$component['abatement'],'charges_aggregate'=>